class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        if n < k * m:
            return -inf

        dp = [[0] * (m+1) for _ in range(n)]
        prefix_sum = [0]
        for num in nums:
            prefix_sum.append(prefix_sum[-1] + num)

        # Calculate prefix sums for each subarray of length m starting from index i
        for i in range(m):
            dp[i][1] = prefix_sum[i+m] - prefix_sum[i]

        # Fill the DP table
        for i in range(m, n):
            for j in range(2, min(k+1, m+1)):
                dp[i][j] = max(dp[i-m][j-1] + prefix_sum[i+j] - prefix_sum[i], dp[i-1][j])

        return max(dp[n-1])

