class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        dp = [[0 for _ in range(k+1)] for _ in range(n+1)]

        # Base case: empty subarray
        for i in range(1, n+1):
            dp[i][0] = nums[i-1]

        # Fill the DP table
        for i in range(1, n+1):
            for j in range(1, min(k, i//m)+1):
                if i < m*j:
                    dp[i][j] = dp[i-1][j]
                else:
                    dp[i][j] = max(dp[i-m*j][j-1] + sum(nums[i-j*m:i]), dp[i-1][j])

        return dp[n][k]

