        # Calculate prefix sums
        for i in range(1, n + 1):
            prefix_sum[i] = prefix_sum[i - 1] + nums[i - 1]

        # Fill dp table
        for i in range(1, n + 1):
            for j in range(1, min(k + 1, i // m + 1)):
                if i - j * m >= 0:
                    dp[i][j] = max(dp[i - 1][j], prefix_sum[i] - prefix_sum[i - j * m])
                else:
                    dp[i][j] = dp[i - 1][j]

        return dp[n][k]

