class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        if len(nums) < k * m:
            return -float('inf')

        dp = [[0 for _ in range(m)] for _ in range(k)]
        prefix_sum = [0]
        for num in nums:
            prefix_sum.append(prefix_sum[-1] + num)

        for i in range(1, k + 1):
            for j in range(1, m + 1):
                if i == 1:
                    dp[i][j] = max(dp[i][j], prefix_sum[j] - prefix_sum[j - m])
                else:
                    dp[i][j] = max(dp[i][j], prefix_sum[j] - prefix_sum[j - m] + dp[i - 1][j - 1])

        return dp[k][m]

