class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        if n < k * m:
            return float('-inf')

        dp = [[0] * (m+1) for _ in range(n)]
        cur_sum = 0

        for i in range(n):
            cur_sum += nums[i]
            if i >= k * m:
                cur_sum -= nums[i-k*m]

            for j in range(1, min(m+1, i//k + 1)):
                dp[i][j] = max(dp[i][j], dp[i-k*m][j-1] + cur_sum)

        return dp[n-1][m]

