class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        # Calculate prefix sums
        prefix_sums = [0] * (len(nums) + 1)
        for i in range(1, len(prefix_sums)):
            prefix_sums[i] = prefix_sums[i-1] + nums[i-1]

        # Initialize variables to keep track of the maximum sum
        max_sum = float('-inf')
        current_sum = 0

        # Iterate through the array to find the maximum sum of k subarrays of length m
        for i in range(k, len(nums) + 1):
            if i - k < m:
                current_sum += prefix_sums[i] - prefix_sums[i-k]
            else:
                current_sum += prefix_sums[i] - prefix_sums[i-m]

            max_sum = max(max_sum, current_sum)

        return max_sum

