    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        if n < k * m:
            return -inf

        dp = [[0] * (m+1) for _ in range(n)]
        prefix_sum = [0] * (n+1)
        for i in range(1, n+1):
            prefix_sum[i] = prefix_sum[i-1] + nums[i-1]

        # Calculate the sum of the first m elements
        initial_sum = prefix_sum[m]

        # Fill the dp table
        for i in range(m, n):
            dp[i][1] = max(dp[i-m][1] + prefix_sum[i] - prefix_sum[i-m], initial_sum)
            for j in range(2, min(i, k)):
                dp[i][j] = max(dp[i-m][j-1] + prefix_sum[i] - prefix_sum[i-m], dp[i-j][j])

        return dp[n-1][-1]

class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        if len(nums) < k * m:
            return -float('inf')

        # Initialize variables
        dp = [[0] * (m + 1) for _ in range(k + 1)]
        current_sum = 0

        # Calculate the sum of the first k elements
        for i in range(k):
            current_sum += nums[i]

        # Fill the dp table
        for i in range(1, k + 1):
            for j in range(1, m + 1):
                if i > j:
                    dp[i][j] = dp[i - 1][j]
                else:
                    dp[i][j] = max(dp[i - 1][j], current_sum + dp[i - 1][j - 1])

                # Update the current sum by subtracting the first element of the previous subarray
                current_sum -= nums[i - 1]
                current_sum += nums[i + k - 1]

        # Return the maximum sum of k non-overlapping subarrays
        return dp[k][m]

