    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        if n < k * m:
            return -float('inf')

        # Initialize dp arrays for prefix sums
        pre_sum = [0] * (n + 1)
        for i in range(1, n + 1):
            pre_sum[i] = pre_sum[i - 1] + nums[i - 1]

        # Initialize DP table to store maximum sums
        dp = [[0] * (k + 1) for _ in range(n)]

        # Fill the DP table
        for j in range(1, k + 1):
            for i in range(j * m - 1, n):
                dp[i][j] = max(dp[i][j - 1], pre_sum[i + 1] - pre_sum[i - j * m + 1])

