class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        if n < k * m:
            return -float('inf')

        dp = [[0] * m for _ in range(k)]
        cur_sum = 0

        # Initialize the first subarray
        for i in range(m):
            cur_sum += nums[i]
            dp[0][i] = cur_sum

        # Fill the DP table
        for i in range(1, k):
            for j in range(m):
                if j == 0:
                    dp[i][j] = max(dp[i-1][j], nums[i*m+j])
                else:
                    dp[i][j] = max(dp[i-1][j], dp[i-1][j-1] + nums[i*m+j])

        # Find the maximum sum of k non-overlapping subarrays
        result = float('-inf')
        for i in range(k):
            result = max(result, dp[k-1][i])

        return result

