class Solution:
    def solveQueries(self, nums: List[int], queries: List[int]) -> List[int]:
        n = len(nums)
        left = [float('inf')] * n
        right = [float('inf')] * n

        # Find the first occurrence of each number
        num_to_index = defaultdict(list)
        for i in range(n):
            num_to_index[nums[i]].append(i)

        # Calculate the leftmost occurrence for each number
        for num in num_to_index:
            for i in range(len(num_to_index[num])):
                if i > 0:
                    left[num_to_index[num][i]] = min(left[num_to_index[num][i]], num_to_index[num][i-1])

        # Calculate the rightmost occurrence for each number
        for num in num_to_index:
            for i in range(len(num_to_index[num])-1, -1, -1):
                if i < len(num_to_index[num])-1:
                    right[num_to_index[num][i]] = min(right[num_to_index[num][i]], num_to_index[num][i+1])

        # Find the closest occurrences for each query
        result = []
