        dp[0][0] = 0

        # Fill the DP table
        for i in range(1, k+1):
            for j in range(1, n+1):
                if s[j-1] == 'N':
                    dp[i][j] = max(dp[i][j], dp[i-1][j-1])
                elif s[j-1] == 'S':
                    dp[i][j] = max(dp[i][j], dp[i-1][j+1])
