        n = len(combined_string)
        dp = [[0] * n for _ in range(n)]

        # Fill the DP table
        for i in range(n):
            dp[i][i] = 1  # Single character is always a palindrome
            for j in range(i - 1, -1, -1):
                if combined_string[i] == combined_string[j]:
                    dp[i][j] = dp[i-1][j+1] + 2
                else:
                    dp[i][j] = max(dp[i-1][j], dp[i][j+1])

        # The result is the length of the longest palindromic subsequence in the combined string
        return dp[n-1][0]

